// Base58 (Bitcoin alphabet) encode/decode implemented manually over plain
// arrays of byte values (numbers 0-255). No Buffer / Uint8Array usage.

export const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

const INDEXES = new Map();
for (let i = 0; i < ALPHABET.length; i++) {
  INDEXES.set(ALPHABET[i], i);
}

// bytes: array of integers 0-255 -> base58 string
export function b58encode(bytes) {
  // count leading zero bytes; each becomes a leading '1'
  let zeros = 0;
  while (zeros < bytes.length && bytes[zeros] === 0) zeros++;

  let encoded = '';
  if (zeros < bytes.length) {
    // convert the remaining big-endian base-256 number into base-58
    const digits = [0]; // little-endian base-58 digits
    for (let i = zeros; i < bytes.length; i++) {
      let carry = bytes[i];
      for (let j = 0; j < digits.length; j++) {
        carry += digits[j] << 8;
        digits[j] = carry % 58;
        carry = (carry / 58) | 0;
      }
      while (carry > 0) {
        digits.push(carry % 58);
        carry = (carry / 58) | 0;
      }
    }
    for (let i = digits.length - 1; i >= 0; i--) {
      encoded += ALPHABET[digits[i]];
    }
  }

  return '1'.repeat(zeros) + encoded;
}

// str: base58 string -> array of integers 0-255
// throws an Error mirroring Python's ValueError on invalid characters
export function b58decode(str) {
  // count leading '1's; each becomes a leading zero byte
  let zeros = 0;
  while (zeros < str.length && str[zeros] === '1') zeros++;

  const out = new Array(zeros).fill(0);
  if (zeros < str.length) {
    const bytes = [0]; // little-endian base-256 bytes
    for (let i = zeros; i < str.length; i++) {
      let carry = INDEXES.get(str[i]);
      if (carry === undefined) {
        throw new Error(`Invalid character ${JSON.stringify(str[i])}`);
      }
      for (let j = 0; j < bytes.length; j++) {
        carry += bytes[j] * 58;
        bytes[j] = carry & 0xff;
        carry >>= 8;
      }
      while (carry > 0) {
        bytes.push(carry & 0xff);
        carry >>= 8;
      }
    }
    for (let i = bytes.length - 1; i >= 0; i--) {
      out.push(bytes[i]);
    }
  }

  return out;
}

