// Helpers to reproduce Python semantics for bytes objects:
// - utf8Encode: equivalent of Python's str.encode() (UTF-8)
// - bytesRepr:  equivalent of Python's repr(bytes) as produced by print()

// str -> array of integers 0-255 (UTF-8 encoding, as Python str.encode())
export function utf8Encode(str) {
  const bytes = [];
  for (const ch of str) { // iterates by Unicode code point
    const cp = ch.codePointAt(0);
    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }
  return bytes;
}

// bytes: array of integers 0-255 -> Python repr string, e.g. b'\x00abc'
export function bytesRepr(bytes) {
  const hasSingle = bytes.includes(0x27); // '
  const hasDouble = bytes.includes(0x22); // "
  // Python prefers single quotes, switching to double quotes only when the
  // data contains a single quote but no double quote
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const quoteCode = quote.charCodeAt(0);

  let out = 'b' + quote;
  for (const b of bytes) {
    if (b === 0x5c) {
      out += '\\\\';
    } else if (b === quoteCode) {
      out += '\\' + quote;
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + b.toString(16).padStart(2, '0');
    }
  }
  return out + quote;
}

