// Minimal re-implementation of the argparse behaviour used by test15.py:
// required string options given as `--name value` or `--name=value`.
// On missing arguments it prints a usage/error message to stderr and exits
// with status code 2, matching Python's argparse.

import { basename } from 'node:path';

const PROG = basename(process.argv[1] || 'test15.mjs');

function usage() {
  return `usage: ${PROG} [-h] --a A --b B --c C --d D`;
}

function fail(message) {
  process.stderr.write(usage() + '\n');
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

export function parseArgs(argv) {
  const required = ['a', 'b', 'c', 'd'];
  const result = {};

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token === '-h' || token === '--help') {
      process.stdout.write(usage() + '\n');
      process.exit(0);
    }
    if (!token.startsWith('--')) {
      fail(`unrecognized arguments: ${token}`);
    }
    let name;
    let value;
    const eq = token.indexOf('=');
    if (eq !== -1) {
      name = token.slice(2, eq);
      value = token.slice(eq + 1);
    } else {
      name = token.slice(2);
      if (i + 1 >= argv.length) {
        fail(`argument --${name}: expected one argument`);
      }
      value = argv[++i];
    }
    if (!required.includes(name)) {
      fail(`unrecognized arguments: --${name}`);
    }
    result[name] = value;
  }

  const missing = required.filter((k) => !(k in result));
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.map((k) => '--' + k).join(', ')}`);
  }

  return result;
}

