import { parseArgs } from './lib/argparse.mjs';
import { b58encode, b58decode } from './lib/base58.mjs';
import { utf8Encode, bytesRepr } from './lib/pybytes.mjs';

const args = parseArgs(process.argv.slice(2));

const enc1 = b58encode(utf8Encode(args.a)); // 编码字符串1
const enc2 = b58encode(utf8Encode(args.b)); // 编码字符串2

let dec1;
let dec2;
try {
  dec1 = b58decode(args.c); // 解码Base58字符串1
  dec2 = b58decode(args.d); // 解码Base58字符串2
} catch (err) {
  // mirror Python's uncaught ValueError: message on stderr, exit code 1
  process.stderr.write(`ValueError: ${err.message}\n`);
  process.exit(1);
}

// base58.b58encode returns bytes; printing bytes yields their repr (b'...')
console.log(bytesRepr([...enc1].map((ch) => ch.charCodeAt(0))));
console.log(bytesRepr([...enc2].map((ch) => ch.charCodeAt(0))));
console.log(bytesRepr(dec1));
console.log(bytesRepr(dec2));

